CREATE TABLE organizations (id text PRIMARY KEY, name text NOT NULL);
CREATE TABLE users (id text PRIMARY KEY, email text NOT NULL UNIQUE, password_hash text NOT NULL, organization_id text NOT NULL REFERENCES organizations(id), role text NOT NULL DEFAULT 'admin');
CREATE TABLE prospects (id text PRIMARY KEY, organization_id text NOT NULL REFERENCES organizations(id), name text NOT NULL, email text NOT NULL, company text NOT NULL, stage text NOT NULL DEFAULT 'Outreach', created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(organization_id,email));
CREATE TABLE projects (id text PRIMARY KEY, organization_id text NOT NULL REFERENCES organizations(id), name text NOT NULL, client text NOT NULL, status text NOT NULL DEFAULT 'Planning', created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(id,organization_id));
CREATE TABLE tasks (id text PRIMARY KEY, organization_id text NOT NULL REFERENCES organizations(id), project_id text NOT NULL, title text NOT NULL, status text NOT NULL DEFAULT 'To do', priority text NOT NULL DEFAULT 'Medium', created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(project_id,organization_id) REFERENCES projects(id,organization_id));
CREATE TABLE audits (id text PRIMARY KEY, organization_id text NOT NULL REFERENCES organizations(id), actor_id text NOT NULL, action text NOT NULL, resource_id text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
